        "synopsis":  "*15세 이상 이용가능 *본 작품은 픽션이며 등장하는 인물, 사건, 지명 등은 실존하는 것과 일체 관계가 없습니다. 고대 이집트에 관심이 많은 의대생 장이현. 그는 유적을 보기 위해 이집트로 답사를 떠났다가 넓은 유적에서 길을 잃고 도굴꾼들과 맞닥뜨리게 된다. 이현은 그들에게 붙잡혀 석관 안에 갇히게 되었지만 숨 막히는 위기 속에서 가까스로 탈출에 성공한다. 그리고 석관 앞에 서 있던, 마치 살아 숨 쉬는 것 같은 조각상과 마주하게 되는데. 넋을 잃고 조각상을 바라보던 이현은 곧 정신을 차리고 길을 찾아 헤매지만 머지않아 또다시 도굴꾼들과 마주치고 만다. 결국 수적으로도 체력적으로도 싸움에서 밀리던 절체절명의 순간 이현의 눈앞에서 그 ‘석상’이 살아 숨 쉬며 다가오는데……! “당신이 ‘폭군’이라 불려도 난 포기하지 않아. 이번에야말로 당신을 지킬 거야!” 신비로운 고대 이집트로 타임 슬립, 그곳에서 펼쳐지는 매력적인 이야기가 지금 시작됩니다!",
