        "synopsis":  "불꽃의 봉황이 들판을 불사르네 \u0027화봉요원\u0027은 삼국지를 소재로 하는 가상역사 만화다. 삼국지는 한자를 쓰는 한자문화권으로 통하는 소위 극동 3국, 중국 일본 한국에서 공통적으로 하나의 모델처럼 활용되고 있으며, 삼국지의 각색물은 3국 모두에서 다양한 작가들에 의해 여러가지 판본으로 각색 개작되어 왔으며, 당연히 많은 인물이 등장하기 때문에 다양한 인물상을 만들어내서 조명하는 것을 통하여 작가의 개성과 필력이 드러나며 해당 작가가 살던 시대상이 반영되는 등, 여러가지 감상 포인트가 있어서 긴 시간이 흘러도 꾸준히 선호되는 소재이기도 하다. 화봉요원은 그런 삼국지 각색물 중에서도 비교적 최근에 나온 작품에 속하며(2002년부터 연재 시작), 각색의 가장 큰 특징으로는 어지간한 삼국지 각색물에서는 최종 보스로 취급되기 쉬운 \u0027사마의\u0027와 (작품의 내용 까발림이 되기 때문에 누군지 적을 수 없는) 또 다른 한 명의 장수를 통하여 흔한 삼국지의 다른 버전으로~의 이야기가 아니라, 강한 인상의 캐릭터가 살아있는 먼치킨 무협물과 홍콩 느와르에 가까운 이야기를 펼친다고 할 수 있다. 그리고 대부분의 캐릭터들이 기존의 삼국지에서 보던 인물들과는 다른 인상을 갖도록 하기 위해, 일부러 이중신분 등을 통한 신분 세탁 과정을 거치거나 삼국지연의에서 나오지 않던 과거사를 적극적으로 그리는 등으로 다른 삼국지 각색물에 등장하는 같은 인물이라도 전혀 다른 느낌을 받을 수 있게 많은 공을 들여서 묘사하고 있는 것도 특징이다. 선이 굵은 그림으로 처절하고 강렬한 전투와 다양한 인물간의 이야기를 그리는 군상극으로의 완성도도 높으며 자신이 아는 삼국지와 다른 면을 찾으며 즐길 수도 있는, 재미있는 중국만화이다. 본작 화봉요원은 과거에 한번 한국어판이 발매가 되었었으나, 이런저런 사정으로 인하여 초반 전개만 나오고 발매가 중지가 되었지만 전자책으로 곧 다시 독자들을 찾아가게 되었으므로, 많은 독자들의 기대를 바란다.",
